#[summary("clamp an i64 to a closed range")]
mod tasks {
    #[effects(pure)]
    #[uses(clamped)]
    fn clamp(x: i64, lo: i64, hi: i64) -> (r: i64)
        requires ordered(lo, hi),
        ensures clamped(x, lo, hi, r),
    {
        if x < lo {
            lo
        } else if x > hi {
            hi
        } else {
            x
        }
    }

    spec fn clamped(x: i64, lo: i64, hi: i64, r: i64) -> bool {
        if x < lo {
            r == lo
        } else if x > hi {
            r == hi
        } else {
            r == x
        }
    }

    spec fn ordered(lo: i64, hi: i64) -> bool {
        lo <= hi
    }
}

#[summary("floor midpoint of two i64 without overflow")]
mod tasks {
    spec fn is_floor_mid(a: i64, b: i64, r: i64) -> bool {
        2 * r <= a + b && a + b < 2 * r + 2
    }

    #[effects(pure)]
    #[uses(is_floor_mid)]
    fn midpoint(a: i64, b: i64) -> (r: i64)
        ensures is_floor_mid(a, b, r),
    {
        let x: i64 = a / 2;
        let y: i64 = b / 2;
        let s: i64 = a % 2 + b % 2;
        let t: i64 = if s < 0 {
            -1
        } else if s >= 2 {
            1
        } else {
            0
        };
        x + y + t
    }
}

#[summary("saturating sum of a slice")]
mod tasks {
    spec fn inv(a: &[i64], i: usize, s: i64) -> bool {
        i <= a.len() && s == sat_prefix(a, i)
    }

    spec fn is_sat_sum(a: &[i64], r: i64) -> bool {
        r == sat_prefix(a, a.len())
    }

    spec fn sat_prefix(a: &[i64], n: usize) -> i64
        decreases n,
    {
        if n == 0 {
            0
        } else {
            sat_step(sat_prefix(a, n - 1), a[n - 1])
        }
    }

    spec fn sat_step(s: i64, x: i64) -> i64 {
        if s + x > 9223372036854775807 {
            9223372036854775807
        } else if s + x < -9223372036854775808 {
            -9223372036854775808
        } else {
            s + x
        }
    }

    #[effects(pure)]
    #[uses(inv, is_sat_sum, sat_prefix, sat_step)]
    fn sat_sum(a: &[i64]) -> (r: i64)
        ensures is_sat_sum(a, r),
    {
        let mut s: i64 = 0;
        let mut i: usize = 0;
        while i < a.len()
            invariant inv(a, i, s),
            decreases a.len() - i,
        {
            let x: i64 = a[i];
            let t: i64 = if x > 0 {
                if s > 9223372036854775807 - x {
                    9223372036854775807
                } else {
                    s + x
                }
            } else {
                if s < i64::MIN - x {
                    i64::MIN
                } else {
                    s + x
                }
            };
            s = t;
            i = i + 1;
        }
        s
    }
