#[summary("count elements in inclusive range")]
mod tasks {
    #[effects(pure)]
    #[uses(count_prefix, inv_ok, n_ok, res_ok)]
    fn count_in_range(a: &[i64], lo: i64, hi: i64) -> (r: usize)
        ensures res_ok(a, lo, hi, r),
    {
        let mut i: usize = 0;
        let mut c: usize = 0;
        while i < a.len()
            invariant n_ok(a, i), inv_ok(a, lo, hi, i, c),
            decreases a.len() - i,
        {
            if lo <= a[i] && a[i] <= hi {
                c = c + 1;
            }
            i = i + 1;
        }
        c
    }

    spec fn count_prefix(a: &[i64], lo: i64, hi: i64, n: usize) -> usize
        decreases n,
    {
        if n == 0 {
            0
        } else {
            count_prefix(a, lo, hi, n - 1) + (if lo <= a[n - 1] && a[n - 1] <= hi { 1 } else { 0 })
        }
    }

    spec fn inv_ok(a: &[i64], lo: i64, hi: i64, i: usize, c: usize) -> bool {
        c <= i && c == count_prefix(a, lo, hi, i)
    }

    spec fn n_ok(a: &[i64], n: usize) -> bool {
        n <= a.len()
    }

    spec fn res_ok(a: &[i64], lo: i64, hi: i64, r: usize) -> bool {
        r == count_prefix(a, lo, hi, a.len())
    }
}

#[summary("first index of maximum element")]
mod tasks {
    #[effects(pure)]
    #[uses(first_upto, is_first_max, max_upto, non_empty)]
    fn first_max_index(a: &[i64]) -> (r: usize)
        requires non_empty(a),
        ensures is_first_max(a, r),
    {
        let mut best: usize = 0;
        let mut i: usize = 1;
        while i < a.len()
            invariant max_upto(a, best, i), first_upto(a, best), i <= a.len(),
            decreases a.len() - i,
        {
            if a[i] > a[best] {
                best = i;
            }
            i = i + 1;
        }
        best
    }

    spec fn first_upto(a: &[i64], b: usize) -> bool {
        b < a.len() && (forall|j: usize| j < b ==> #[trigger] a[j] < a[b])
    }

    spec fn is_first_max(a: &[i64], r: usize) -> bool {
        max_upto(a, r, a.len()) && first_upto(a, r)
    }

    spec fn max_upto(a: &[i64], b: usize, n: usize) -> bool {
        b < n && n <= a.len() && (forall|j: usize| j < n ==> #[trigger] a[j] <= a[b])
    }

    spec fn non_empty(a: &[i64]) -> bool {
        a.len() > 0
    }
}

