#[summary("strictly increasing check")]
mod tasks {
    spec fn full(a: &[i64]) -> bool {
        forall|j: usize| j + 1 < a.len() ==> #[trigger] a[j] < a[j + 1]
    }

    spec fn inv(a: &[i64], i: usize, ok: bool) -> bool {
        i <= a.len() && ok == upto(a, i + 1)
    }

    spec fn res_ok(a: &[i64], r: bool) -> bool {
        r == full(a)
    }

    #[effects(pure)]
    #[uses(full, inv, res_ok, upto)]
    fn strictly_increasing(a: &[i64]) -> (r: bool)
        ensures res_ok(a, r),
    {
        let n: usize = a.len();
        let mut i: usize = 0;
        let mut ok: bool = true;
        while i + 1 < n
            invariant inv(a, i, ok),
            decreases n - i,
        {
            if a[i] >= a[i + 1] {
                ok = false;
            }
            i = i + 1;
        }
        ok
    }

    spec fn upto(a: &[i64], k: usize) -> bool {
        forall|j: usize| j + 1 < k && j + 1 < a.len() ==> #[trigger] a[j] < a[j + 1]
    }
}

#[summary("binary search lower_bound")]
mod tasks {
    spec fn above_ok(a: &[i64], t: i64, hi: usize) -> bool {
        forall|k: usize| hi <= k && k < a.len() ==> t <= #[trigger] a[k]
    }

    spec fn below_ok(a: &[i64], t: i64, lo: usize) -> bool {
        forall|k: usize| k < lo && lo <= a.len() ==> #[trigger] a[k] < t
    }

    spec fn bounds(a: &[i64], lo: usize, hi: usize) -> bool {
        lo <= hi && hi <= a.len()
    }

    spec fn is_lb(a: &[i64], t: i64, r: usize) -> bool {
        r <= a.len() && below_ok(a, t, r) && above_ok(a, t, r)
    }

    #[effects(pure)]
    #[uses(above_ok, below_ok, bounds, is_lb, sorted)]
    fn lower_bound(a: &[i64], t: i64) -> (r: usize)
        requires sorted(a),
        ensures is_lb(a, t, r),
    {
        let mut lo: usize = 0;
        let mut hi: usize = a.len();
        while lo < hi
            invariant bounds(a, lo, hi), below_ok(a, t, lo), above_ok(a, t, hi), sorted(a),
            decreases hi - lo,
        {
            let mid: usize = lo + (hi - lo) / 2;
            if a[mid] < t {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        lo
    }

    spec fn sorted(a: &[i64]) -> bool {
        forall|i: usize, j: usize| i <= j && j < a.len() ==> #[trigger] a[i] <= #[trigger] a[j]
    }
}

