#[summary("second largest distinct value")]
mod tasks {
    spec fn all_eq(a: &[i64], n: usize, v: i64) -> bool {
        forall|i: usize| i < n && n <= a.len() ==> #[trigger] a[i] == v
    }

    spec fn all_le(a: &[i64], n: usize, v: i64) -> bool {
        forall|i: usize| i < n && n <= a.len() ==> #[trigger] a[i] <= v
    }

    spec fn all_m_or_le(a: &[i64], n: usize, m: i64, s: i64) -> bool {
        forall|i: usize| i < n && n <= a.len() ==> #[trigger] a[i] == m || a[i] <= s
    }

    spec fn has(a: &[i64], n: usize, v: i64) -> bool {
        exists|i: usize| i < n && n <= a.len() && #[trigger] a[i] == v
    }

    spec fn has_below(a: &[i64], n: usize, m: i64) -> bool {
        exists|i: usize| i < n && n <= a.len() && #[trigger] a[i] < m
    }

    spec fn inv(a: &[i64], n: usize, m: i64, s: i64) -> bool {
        all_le(a, n, m) && (n == 0 ==> m == i64::MIN) && (n > 0 ==> has(a, n, m)) && s <= m && (s == i64::MIN || has(a, n, s) && s < m) && all_m_or_le(a, n, m, s)
    }

    #[effects(pure)]
    #[uses(all_eq, all_le, all_m_or_le, has, has_below, inv, second_ok)]
    fn second_max(a: &[i64]) -> (r: i64)
        ensures second_ok(a, r),
    {
        let mut m: i64 = i64::MIN;
        let mut s: i64 = i64::MIN;
        let mut i: usize = 0;
        while i < a.len()
            invariant i <= a.len(), inv(a, i, m, s),
            decreases a.len() - i,
        {
            let x: i64 = a[i];
            if x > m {
                s = m;
                m = x;
            } else if x < m && x > s {
                s = x;
            }
            i = i + 1;
        }
        s
    }

    spec fn second_ok(a: &[i64], r: i64) -> bool {
        a.len() == 0 && r == i64::MIN || (exists|m: i64| #[trigger] has(a, a.len(), m) && all_le(a, a.len(), m) && (has_below(a, a.len(), m) ==> has(a, a.len(), r) && r < m && all_m_or_le(a, a.len(), m, r)) && (all_eq(a, a.len(), m) ==> r == i64::MIN))
    }
}

#[summary("In-place rotate right via three reversals")]
mod tasks {
    spec fn rev_inv(a: &[i64], o: &[i64], lo: usize, hi: usize, i: usize, j: usize) -> bool {
        a.len() == o.len() && lo <= i && i <= j && j <= hi && i + j == lo + hi && (forall|x: usize| x < a.len() ==> (x < lo || x >= hi ==> #[trigger] a[x] == o[x]) && (lo <= x && x < i ==> a[x] == o[lo + hi - 1 - x]) && (j <= x && x < hi ==> a[x] == o[lo + hi - 1 - x]) && (i <= x && x < j ==> a[x] == o[x]))
    }

    spec fn rev_post(a: &[i64], o: &[i64], lo: usize, hi: usize) -> bool {
        a.len() == o.len() && (forall|x: usize| x < a.len() ==> (x < lo || x >= hi ==> #[trigger] a[x] == o[x]) && (lo <= x && x < hi ==> a[x] == o[lo + hi - 1 - x]))
    }

    spec fn rev_pre(a: &[i64], lo: usize, hi: usize) -> bool {
        lo <= hi && hi <= a.len()
    }

    #[effects(pure)]
    #[uses(rev_inv, rev_post, rev_pre)]
    fn reverse(a: &mut [i64], lo: usize, hi: usize) -> ()
        requires rev_pre(a, lo, hi),
        ensures rev_post(a, old(a), lo, hi),
    {
        let mut i: usize = lo;
        let mut j: usize = hi;
        while i + 1 < j
            invariant rev_inv(a, old(a), lo, hi, i, j),
            decreases j - i,
        {
            let t: i64 = a[i];
            let u: i64 = a[j - 1];
            a[i] = u;
            a[j - 1] = t;
            i = i + 1;
            j = j - 1;
        }
    }

    spec fn rot_post(a: &[i64], o: &[i64], k: usize) -> bool {
        a.len() == o.len() && (forall|i: usize| i < o.len() ==> (i + k % a.len() < a.len() ==> a[i + k % a.len()] == #[trigger] o[i]) && (i + k % a.len() >= a.len() ==> a[i + k % a.len() - a.len()] == o[i]))
    }

    #[effects(pure)]
    #[uses(rev_post, rev_pre, rot_post)]
    fn rotate_right(a: &mut [i64], k: usize) -> ()
        ensures rot_post(a, old(a), k),
    {
        let n: usize = a.len();
        if n > 1 {
            let m: usize = k % n;
            reverse(a, 0, n);
            reverse(a, 0, m);
            reverse(a, m, n);
        }
    }
}

#[summary("Deduplicate a sorted slice in place, zero-filling the tail.")]
mod tasks {
    spec fn back_all(o: &[i64], a: &[i64], w: usize, i: usize) -> bool {
        forall|j: usize| j < w && w <= a.len() && i < o.len() ==> #[trigger] has(o, i + 1, a[j])
    }

    #[effects(pure)]
    #[uses(back_all, back_one, has, has_grow, len_gt)]
    fn back_lemma(o: &[i64], a: &[i64], w: usize, i: usize) -> ()
        requires back_one(o, a, w, i), has_grow(o, i), len_gt(o, i),
        ensures back_all(o, a, w, i),
    {}

    spec fn back_one(o: &[i64], a: &[i64], w: usize, i: usize) -> bool {
        forall|j: usize| j < w && w <= a.len() && i <= o.len() ==> #[trigger] has(o, i, a[j])
    }

    spec fn bound_ok(a: &[i64], w: usize) -> bool {
        w <= a.len()
    }

    spec fn covered(src: &[i64], m: usize, dst: &[i64], w: usize) -> bool {
        forall|k: usize| k < m && m <= src.len() ==> #[trigger] has(dst, w, src[k])
    }

