    #[uses(bound_ok, covered, has, last_is, ordered_at, same_tail, sorted, step_carry, step_pre, step_shape, strict_prefix, zero_post, zero_pre, zero_range)]
    fn dedup_sorted(a: &mut [i64]) -> (r: usize)
        requires sorted(a),
        ensures bound_ok(a, r), strict_prefix(a, r), covered(old(a), old(a).len(), a, r), covered(a, r, old(a), old(a).len()), zero_range(a, r, a.len()),
    {
        let n: usize = a.len();
        if n == 0 {
            0
        } else {
            let mut w: usize = 1;
            let mut i: usize = 1;
            while i < n
                invariant 1 <= w, w <= i, i <= n, a.len() == n, sorted(old(a)), strict_prefix(a, w), last_is(a, w, old(a), i), covered(old(a), i, a, w), covered(a, w, old(a), n), same_tail(a, old(a), i),
                decreases n - i,
            {
                assert(old(a)[i - 1] <= old(a)[i]);
                assert(a[i] == old(a)[i]);
                assert(has(old(a), n, old(a)[i]));
                w = step(a, w, i);
                i = i + 1;
            }
            let mut z: usize = w;
            while z < n
                invariant w <= z, z <= n, a.len() == n, strict_prefix(a, w), covered(old(a), n, a, w), covered(a, w, old(a), n), zero_range(a, w, z),
                decreases n - z,
            {
                zero_at(a, w, z);
                z = z + 1;
            }
            w
        }
    }

    #[effects(pure)]
    #[uses(has, has_grow, has_self, len_gt)]
    fn grow_lemma(o: &[i64], i: usize) -> ()
        requires len_gt(o, i),
        ensures has_grow(o, i), has_self(o, i),
