    }

    spec fn run_at(a: &[i64], s: usize, l: usize) -> bool {
        s + l <= a.len() && (forall|k: usize| s <= k && k + 1 < s + l ==> #[trigger] a[k] == a[k + 1])
    }

    spec fn witness(a: &[i64], b: usize) -> bool {
        b == 0 || (exists|s: usize| #[trigger] run_at(a, s, b))
    }
}

#[summary("merge two sorted slices")]
mod tasks {
    spec fn agree(s: &[i64], t: &[i64], n: usize) -> bool {
        n <= s.len() && n <= t.len() && (forall|p: usize| p < n ==> #[trigger] s[p] == t[p])
    }

    spec fn cnt(s: &[i64], n: usize, v: i64) -> i64
        decreases n,
    {
        if n == 0 || n > s.len() {
            0
        } else {
            cnt(s, n - 1, v) + (if s[n - 1] == v { 1 } else { 0 })
        }
    }

    #[effects(pure)]
    #[uses(agree, cnt, frame_post)]
    fn frame(s: &[i64], t: &[i64], n: usize) -> ()
        requires agree(s, t, n),
        ensures frame_post(s, t, n),
        decreases n,
    {
        if n > 0 {
            frame(s, t, n - 1);
        }
    }

    spec fn frame_post(s: &[i64], t: &[i64], n: usize) -> bool {
        forall|v: i64| #[trigger] cnt(s, n, v) == cnt(t, n, v)
    }

    spec fn inv(a: &[i64], b: &[i64], o: &[i64], i: usize, j: usize) -> bool {
        i <= a.len() && j <= b.len() && o.len() == a.len() + b.len() && sorted(o, i + j) && (i + j > 0 && i < a.len() ==> o[i + j - 1] <= a[i]) && (i + j > 0 && j < b.len() ==> o[i + j - 1] <= b[j]) && (forall|v: i64| #[trigger] cnt(o, i + j, v) == cnt(a, i, v) + cnt(b, j, v))
    }

    spec fn lens_ok(a: &[i64], b: &[i64], o: &[i64]) -> bool {
        o.len() == a.len() + b.len()
    }

    #[effects(pure)]
    #[uses(cnt, inv, lens_ok, put_post, put_pre, same_multiset, sorted)]
    fn merge_sorted(a: &[i64], b: &[i64], out: &mut [i64]) -> ()
        requires sorted(a, a.len()), sorted(b, b.len()), lens_ok(a, b, out),
        ensures sorted(out, out.len()), same_multiset(a, b, out), lens_ok(a, b, out),
    {
        let mut i: usize = 0;
        let mut j: usize = 0;
        while i < a.len() || j < b.len()
            invariant inv(a, b, out, i, j), sorted(a, a.len()), sorted(b, b.len()),
            decreases a.len() + b.len() - i - j,
        {
            if j >= b.len() || i < a.len() && a[i] <= b[j] {
                put(out, i + j, a[i], i + j);
                i = i + 1;
            } else {
                put(out, i + j, b[j], i + j);
                j = j + 1;
            }
        }
    }

    #[effects(pure)]
    #[uses(cnt, put_post, put_pre)]
    fn put(o: &mut [i64], k: usize, x: i64, n: usize) -> ()
        requires put_pre(o, k, n),
        ensures put_post(o, old(o), k, x, n),
        decreases n,
    {
        if n == 0 {
            o[k] = x;
        } else {
            put(o, k, x, n - 1);
        }
    }

    spec fn put_post(o: &[i64], old_o: &[i64], k: usize, x: i64, n: usize) -> bool {
        o.len() == old_o.len() && k < o.len() && o[k] == x && (forall|p: usize| p < o.len() && p != k ==> #[trigger] o[p] == old_o[p]) && (forall|v: i64| #[trigger] cnt(o, n, v) == cnt(old_o, n, v))
    }

    spec fn put_pre(o: &[i64], k: usize, n: usize) -> bool {
        k < o.len() && n <= k
    }

    spec fn same_multiset(a: &[i64], b: &[i64], o: &[i64]) -> bool {
        forall|v: i64| #[trigger] cnt(o, o.len(), v) == cnt(a, a.len(), v) + cnt(b, b.len(), v)
    }

    spec fn sorted(s: &[i64], n: usize) -> bool {
        n <= s.len() && (forall|p: usize| p + 1 < n ==> #[trigger] s[p] <= s[p + 1])
    }
}

#[summary("sorting")]
mod tasks {
    spec fn hole(a: &[i64], i: usize, j: usize) -> bool {
        i < a.len() && j <= i && (forall|p: usize, q: usize| p < q && q <= i && p != j && q != j ==> #[trigger] a[p] <= #[trigger] a[q]) && (forall|r: usize| j < r && r <= i ==> a[j] <= #[trigger] a[r])
    }

    #[effects(pure)]
    #[uses(hole, sorted, sorted_prefix)]
    fn sort(a: &mut [i64]) -> ()
        ensures sorted(a),
    {
        let n: usize = a.len();
        let mut i: usize = 0;
        while i < n
            invariant i <= n, n == a.len(), sorted_prefix(a, i),
            decreases n - i,
        {
            let mut j: usize = i;
            while j > 0 && a[j - 1] > a[j]
                invariant j <= i, i < n, n == a.len(), hole(a, i, j),
                decreases j,
            {
                let t: i64 = a[j - 1];
                a[j - 1] = a[j];
                a[j] = t;
                j = j - 1;
            }
            i = i + 1;
        }
    }

    spec fn sorted(a: &[i64]) -> bool {
        forall|x: usize, y: usize| x < y && y < a.len() ==> #[trigger] a[x] <= #[trigger] a[y]
    }

    spec fn sorted_prefix(a: &[i64], m: usize) -> bool {
        m <= a.len() && (forall|x: usize, y: usize| x < y && y < m ==> #[trigger] a[x] <= #[trigger] a[y])
    }
}

#[summary("modular exponentiation")]
mod tasks {
    spec fn add_mul(a: i64, k: i64, m: i64) -> bool {
        (a + m * k) % m == a % m
    }

    spec fn am_ok(a: i64, k: i64, m: i64) -> bool {
        a >= 0 && k >= 0 && m >= 1
    }

    spec fn assoc(x: i64, y: i64, z: i64, m: i64) -> bool {
        x * (y * z % m) % m == x * y % m * z % m
    }

    spec fn dom(base: i64, exp: i64, m: i64) -> bool {
        0 <= base && 0 <= exp && 1 <= m && m <= 3000000000
    }

    spec fn done(res: i64, base: i64, exp: i64, m: i64) -> bool {
        res == pw(1 % m, base % m, exp, m) && 0 <= res && res < m
    }

    spec fn inv(r: i64, x: i64, e: i64, m: i64, base: i64, exp: i64) -> bool {
        0 <= r && r < m && 0 <= x && x < m && 0 <= e && 1 <= m && m <= 3000000000 && pw(r, x, e, m) == pw(1 % m, base % m, exp, m)
    }

    spec fn l1(x: i64, y: i64, z: i64, m: i64) -> bool {
        x * y * z % m == x * y % m * z % m
    }

    spec fn mod_mul(x: i64, y: i64, m: i64) -> bool {
        x * (y % m) % m == x * y % m
    }

    spec fn ok3(x: i64, y: i64, z: i64, m: i64) -> bool {
        0 <= x && x < m && 0 <= y && y < m && 0 <= z && z < m && m <= 3000000000
    }

    spec fn pos(m: i64) -> bool {
        m >= 1
    }

    spec fn pos_m(m: i64) -> bool {
        m >= 1
    }

    #[effects(pure)]
    #[uses(dom, done, inv, pw)]
    fn pow_mod(base: i64, exp: i64, m: i64) -> (res: i64)
        requires dom(base, exp, m),
        ensures done(res, base, exp, m),
    {
        let mut r: i64 = 1 % m;
        let mut x: i64 = base % m;
        let mut e: i64 = exp;
        while e > 0
            invariant inv(r, x, e, m, base, exp),
            decreases e,
        {
            if e % 2 == 1 {
                r = r * x % m;
                e = e - 1;
            } else {
                x = x * x % m;
                e = e / 2;
            }
        }
        r
    }

    spec fn pw(r: i64, x: i64, e: i64, m: i64) -> i64
        decreases e,
    {
        if e <= 0 {
            r
        } else if e % 2 == 0 {
            pw(r, x * x % m, e / 2, m)
        } else {
            pw(r * x % m, x, e - 1, m)
        }
    }
}
